package io.ledgerflow.ledger.adapter.out.account;

import org.springframework.web.service.annotation.GetExchange;
import org.springframework.web.bind.annotation.PathVariable;

import java.util.List;
import java.util.UUID;

public interface AccountClient {

    @GetExchange("/api/v1/accounts/{id}")
    AccountView account(@PathVariable UUID id);

    /** Only the fields ledger actually needs - not a copy of account's model. */
    record AccountView(UUID id, String name, List<WalletView> wallets) {
        public boolean hasWallet(String label) {
            return wallets.stream().anyMatch(s -> label.equals(s.label()));
        }
    }

    record WalletView(UUID id, String label) {}
}

package io.ledgerflow.ledger.config;

import io.ledgerflow.ledger.adapter.out.account.AccountClient;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.support.RestClientAdapter;
import org.springframework.web.service.invoker.HttpServiceProxyFactory;

@Configuration
class AccountClientConfig {

    @Bean
    AccountClient accountClient(RestClient.Builder builder) {
        // Deliberately no timeout yet. Step 06 makes you feel why that is a bug.
        var rest = builder.baseUrl("http://localhost:8080").build();
        return HttpServiceProxyFactory
                .builderFor(RestClientAdapter.create(rest))
                .build()
                .createClient(AccountClient.class);
    }
}

package io.ledgerflow.ledger.domain.model;

import java.time.Instant;
import java.util.UUID;

public record FundsHold(UUID id, UUID accountId, String walletCode, Status status, Instant expiresAt) {

    public enum Status { HELD, RELEASED, SOLD }

    public static FundsHold hold(UUID accountId, String walletCode, Instant expiresAt) {
        return new FundsHold(UUID.randomUUID(), accountId, walletCode, Status.HELD, expiresAt);
    }
}

package io.ledgerflow.ledger.application;

import io.ledgerflow.ledger.adapter.out.account.AccountClient;
import io.ledgerflow.ledger.domain.model.FundsHold;
import io.ledgerflow.ledger.domain.model.UnknownWalletException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.UUID;

@Service
public class PlaceHold {

    private static final Duration HOLD_FOR = Duration.ofMinutes(10);

    private final AccountClient account;
    private final FundsHoldRepository holds;

    PlaceHold(AccountClient account, FundsHoldRepository holds) {
        this.account = account;
        this.holds = holds;
    }

    @Transactional
    public List<FundsHold> place(UUID accountId, List<String> walletCodes) {
        var account = account.account(accountId);          // the network call

        for (var label : walletCodes) {
            if (!account.hasWallet(label)) throw new UnknownWalletException(accountId, label);
        }

        var expiry = Instant.now().plus(HOLD_FOR);
        return holds.saveAll(walletCodes.stream()
                .map(l -> FundsHold.hold(accountId, l, expiry))
                .toList());
    }
}

package io.ledgerflow.ledger.adapter.in.web;

import io.ledgerflow.ledger.application.PlaceHold;
import io.ledgerflow.ledger.domain.model.FundsHold;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/api/v1/holds")
class HoldController {

    private final PlaceHold placeHold;

    HoldController(PlaceHold placeHold) { this.placeHold = placeHold; }

    record HoldRequest(@NotNull UUID accountId, @NotEmpty List<String> wallets) {}

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    List<FundsHold> place(@Valid @RequestBody HoldRequest req) {
        return placeHold.place(req.accountId(), req.wallets());
    }
}

package io.ledgerflow.ledger;

import io.ledgerflow.ledger.adapter.out.account.AccountClient;
import io.ledgerflow.ledger.application.PlaceHold;
import io.ledgerflow.ledger.domain.model.UnknownWalletException;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.util.List;
import java.util.UUID;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.when;

@Testcontainers
@SpringBootTest
class PlaceHoldIT {

    @Container @ServiceConnection
    static PostgreSQLContainer postgres = new PostgreSQLContainer("postgres:17");

    @Autowired PlaceHold placeHold;
    @MockitoBean AccountClient account;      // account does not have to be running

    private static final UUID ACCOUNT = UUID.fromString("11111111-1111-1111-1111-111111111111");

    @Test
    void refusesAWalletAccountDoesNotKnow() {
        when(account.account(ACCOUNT)).thenReturn(
            new AccountClient.AccountView(ACCOUNT, "Demo Arena",
                List.of(new AccountClient.WalletView(UUID.randomUUID(), "A-12"))));

        assertThatThrownBy(() -> placeHold.place(ACCOUNT, List.of("ZZ-99")))
            .isInstanceOf(UnknownWalletException.class);

        assertThat(placeHold.place(ACCOUNT, List.of("A-12"))).hasSize(1);
    }
}
